package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	if !scanner.Scan() {
		return
	}
	n, _ := strconv.Atoi(scanner.Text())

	a := make([]int, n)
	for i := 0; i < n; i++ {
		scanner.Scan()
		a[i], _ = strconv.Atoi(scanner.Text())
	}

	originalOnes := 0
	for _, v := range a {
		if v == 1 {
			originalOnes++
		}
	}

	// Transform array: 0 -> 1, 1 -> -1
	b := make([]int, n)
	for i := 0; i < n; i++ {
		if a[i] == 0 {
			b[i] = 1
		} else {
			b[i] = -1
		}
	}

	// Kadane's algorithm to find max subarray sum (must pick at least one element)
	maxEndingHere := b[0]
	maxSoFar := b[0]
	for i := 1; i < n; i++ {
		if maxEndingHere+b[i] > b[i] {
			maxEndingHere += b[i]
		} else {
			maxEndingHere = b[i]
		}
		if maxEndingHere > maxSoFar {
			maxSoFar = maxEndingHere
		}
	}

	result := originalOnes + maxSoFar
	fmt.Println(result)
}
